const KALSHI_PREFIXES = ['Reg Time:', 'Total Goals:', 'Match Winner:', 'Moneyline:', 'To Win:', 'Winner:', 'Result:'];

function stripPrefix(s) {
  let clean = (s || '').trim();
  for (const prefix of KALSHI_PREFIXES) {
    const re = new RegExp('^' + prefix.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '\\s*', 'i');
    if (re.test(clean)) { clean = clean.replace(re, '').trim(); break; }
  }
  return clean;
}

const incoming = $input.first().json;
const awayTeam = stripPrefix(incoming.away_team || '');
const homeTeam = stripPrefix(incoming.home_team || '');
const matchupValid = awayTeam.toLowerCase() !== homeTeam.toLowerCase();

return [{ json: { ...incoming, away_team: awayTeam, home_team: homeTeam, matchup_valid: matchupValid } }];

// Cache decision: is there a pick_log row for this matchup generated in the last
// 30 minutes? If so, return it and skip generation (counted as a cache hit).
let rows = [];
try {
  for (const r of $('Get Cache').all().map(i => i.json)) {
    if (Array.isArray(r)) rows = rows.concat(r);
    else if (r && r.created_at) rows.push(r);
    else if (r && Array.isArray(r.data)) rows = rows.concat(r.data);
  }
} catch (e) {}

const now = Date.now();
const FRESH_MS = 30 * 60 * 1000;
let hit = null;
for (const r of rows) {
  const t = r && r.created_at ? new Date(r.created_at).getTime() : NaN;
  if (!isNaN(t) && (now - t) <= FRESH_MS) { hit = r; break; }   // Get Cache orders created_at desc
}

return [{
  json: {
    cache_hit: !!hit,
    cached_response: hit ? (hit.full_response || '') : null,
    cached_tier: hit ? (hit.tier || null) : null,
  }
}];

// Resolve the current NFL season + week from nflverse games.csv (schedules),
// then emit one item per game for that week — the analog of CFBD Get Games.
// nflverse games.csv is a single file spanning 1999->present; team columns are
// abbreviations (KC, BUF, NYG, NYJ, LA, LAC). It is fetched as raw text upstream.
const raw = (() => { try { return $('NFL Get Schedule').first().json.data || ''; } catch (e) { return ''; } })();

const lines = raw.trim().split(/\r?\n/).filter(Boolean);
if (lines.length < 2) {
  return [{ json: { _season: new Date().getFullYear(), _week: 0, _schedule_error: true, _schedule_msg: 'games.csv fetch returned no data' } }];
}
const header = lines[0].split(',');
const idx = {};
header.forEach((h, i) => { idx[h.trim()] = i; });
const col = (cols, name) => { const i = idx[name]; return i === undefined ? '' : (cols[i] == null ? '' : String(cols[i]).trim()); };

const rows = [];
for (let i = 1; i < lines.length; i++) {
  const cols = lines[i].split(',');
  if (cols.length < header.length) continue;
  rows.push(cols);
}

const now = Date.now();
const parseD = s => s ? new Date(s + 'T17:00:00Z').getTime() : null;

// Pick the season whose game window spans "now"; else the latest season present.
const seasonsPresent = [...new Set(rows.map(c => parseInt(col(c, 'season'), 10)).filter(n => !isNaN(n)))].sort((a, b) => b - a);
let season = seasonsPresent[0] || new Date().getFullYear();
for (const s of seasonsPresent) {
  const ds = rows.filter(c => parseInt(col(c, 'season'), 10) === s).map(c => parseD(col(c, 'gameday'))).filter(Boolean);
  if (!ds.length) continue;
  const first = Math.min(...ds), last = Math.max(...ds), wk = 7 * 864e5;
  if (now >= first - wk && now <= last + wk) { season = s; break; }
}

const seasonGames = rows.filter(c => parseInt(col(c, 'season'), 10) === season);

// Resolve week: earliest week that still has an unplayed game (no home_score);
// else the latest week present (whole season already played).
const weeks = [...new Set(seasonGames.map(c => parseInt(col(c, 'week'), 10)).filter(n => !isNaN(n)))].sort((a, b) => a - b);
let week = weeks.length ? weeks[weeks.length - 1] : 1;
for (const w of weeks) {
  const wg = seasonGames.filter(c => parseInt(col(c, 'week'), 10) === w);
  const unplayed = wg.some(c => { const hs = col(c, 'home_score'); return hs === '' || hs == null; });
  if (unplayed) { week = w; break; }
}

const weekGames = seasonGames.filter(c => parseInt(col(c, 'week'), 10) === week);

// Schedule-integrity guard: a truncated/failed games.csv fetch silently yields an
// empty or partial slate, which downstream otherwise reads as "no game matched".
// Distinguish that data problem from a genuinely absent game so the response can
// say "retry" instead of misleadingly claiming the matchup isn't on the slate.
const regGames = weekGames.filter(c => (col(c, 'game_type') || 'REG') === 'REG');
const isRegWeek = weekGames.length > 0 && regGames.length === weekGames.length;
const looksTruncated = rows.length < 100;               // a full games.csv has thousands of rows
const emptySlate = weekGames.length === 0;
const partialSlate = isRegWeek && weekGames.length < 13; // an NFL regular-season week is always 13-16 games
if (looksTruncated || emptySlate || partialSlate) {
  return [{ json: {
    _season: season, _week: week, _schedule_error: true,
    _schedule_msg: looksTruncated ? ('only ' + rows.length + ' schedule rows parsed')
      : emptySlate ? ('week ' + week + ' has no games in the parsed schedule')
      : ('week ' + week + ' returned only ' + weekGames.length + ' of the expected 13-16 games'),
  } }];
}

const emit = weekGames.map(c => ({
  json: {
    _season: season,
    _week: week,
    game_id:        col(c, 'game_id'),
    season:         col(c, 'season'),
    week:           col(c, 'week'),
    game_type:      col(c, 'game_type'),
    gameday:        col(c, 'gameday'),
    weekday:        col(c, 'weekday'),
    gametime:       col(c, 'gametime'),
    away_team:      col(c, 'away_team'),
    home_team:      col(c, 'home_team'),
    away_score:     col(c, 'away_score'),
    home_score:     col(c, 'home_score'),
    away_rest:      col(c, 'away_rest'),
    home_rest:      col(c, 'home_rest'),
    div_game:       col(c, 'div_game'),
    roof:           col(c, 'roof'),
    surface:        col(c, 'surface'),
    spread_line:    col(c, 'spread_line'),
    away_moneyline: col(c, 'away_moneyline'),
    home_moneyline: col(c, 'home_moneyline'),
    total_line:     col(c, 'total_line'),
    away_qb_name:   col(c, 'away_qb_name'),
    home_qb_name:   col(c, 'home_qb_name'),
    stadium:        col(c, 'stadium'),
  }
}));

return emit.length ? emit : [{ json: { _season: season, _week: week, _schedule_error: true, _schedule_msg: 'no games after week filter' } }];

// NFL analog of CFB Match Fixture. NFL Resolve Week emits one item per game for
// the current week (nflverse abbreviations). Map the requested full team names to
// abbreviations by NICKNAME (unique across all 32 teams — this is what keeps the
// two New York and two Los Angeles clubs distinct), then find the week's game and
// attach venue, coordinates, roof, rest and divisional flag for downstream nodes.
const items = $input.all();
const awayReq = $('Parse Teams').first().json.away_team || '';
const homeReq = $('Parse Teams').first().json.home_team || '';

// abbr -> [canonical Odds-API full name, city, nickname]
const TEAMS = {
  ARI:['Arizona Cardinals','Arizona','Cardinals'], ATL:['Atlanta Falcons','Atlanta','Falcons'],
  BAL:['Baltimore Ravens','Baltimore','Ravens'], BUF:['Buffalo Bills','Buffalo','Bills'],
  CAR:['Carolina Panthers','Carolina','Panthers'], CHI:['Chicago Bears','Chicago','Bears'],
  CIN:['Cincinnati Bengals','Cincinnati','Bengals'], CLE:['Cleveland Browns','Cleveland','Browns'],
  DAL:['Dallas Cowboys','Dallas','Cowboys'], DEN:['Denver Broncos','Denver','Broncos'],
  DET:['Detroit Lions','Detroit','Lions'], GB:['Green Bay Packers','Green Bay','Packers'],
  HOU:['Houston Texans','Houston','Texans'], IND:['Indianapolis Colts','Indianapolis','Colts'],
  JAX:['Jacksonville Jaguars','Jacksonville','Jaguars'], KC:['Kansas City Chiefs','Kansas City','Chiefs'],
  LV:['Las Vegas Raiders','Las Vegas','Raiders'], LAC:['Los Angeles Chargers','Los Angeles','Chargers'],
  LA:['Los Angeles Rams','Los Angeles','Rams'], LAR:['Los Angeles Rams','Los Angeles','Rams'],
  MIA:['Miami Dolphins','Miami','Dolphins'], MIN:['Minnesota Vikings','Minnesota','Vikings'],
  NE:['New England Patriots','New England','Patriots'], NO:['New Orleans Saints','New Orleans','Saints'],
  NYG:['New York Giants','New York','Giants'], NYJ:['New York Jets','New York','Jets'],
  PHI:['Philadelphia Eagles','Philadelphia','Eagles'], PIT:['Pittsburgh Steelers','Pittsburgh','Steelers'],
  SEA:['Seattle Seahawks','Seattle','Seahawks'], SF:['San Francisco 49ers','San Francisco','49ers'],
  TB:['Tampa Bay Buccaneers','Tampa Bay','Buccaneers'], TEN:['Tennessee Titans','Tennessee','Titans'],
  WAS:['Washington Commanders','Washington','Commanders'],
};
// abbr -> [stadium, lat, lon, roof(dome|retractable|outdoor), altitude]
const STADIUMS = {
  ARI:['State Farm Stadium',33.5277,-112.2626,'retractable',false],
  ATL:['Mercedes-Benz Stadium',33.7554,-84.4009,'retractable',false],
  BAL:['M&T Bank Stadium',39.2780,-76.6227,'outdoor',false],
  BUF:['Highmark Stadium',42.7738,-78.7870,'outdoor',false],
  CAR:['Bank of America Stadium',35.2258,-80.8528,'outdoor',false],
  CHI:['Soldier Field',41.8623,-87.6167,'outdoor',false],
  CIN:['Paycor Stadium',39.0955,-84.5161,'outdoor',false],
  CLE:['Huntington Bank Field',41.5061,-81.6995,'outdoor',false],
  DAL:['AT&T Stadium',32.7473,-97.0945,'retractable',false],
  DEN:['Empower Field at Mile High',39.7439,-105.0201,'outdoor',true],
  DET:['Ford Field',42.3400,-83.0456,'dome',false],
  GB:['Lambeau Field',44.5013,-88.0622,'outdoor',false],
  HOU:['NRG Stadium',29.6847,-95.4107,'retractable',false],
  IND:['Lucas Oil Stadium',39.7601,-86.1639,'retractable',false],
  JAX:['EverBank Stadium',30.3239,-81.6373,'outdoor',false],
  KC:['Arrowhead Stadium',39.0489,-94.4839,'outdoor',false],
  LV:['Allegiant Stadium',36.0909,-115.1833,'dome',false],
  LAC:['SoFi Stadium',33.9535,-118.3392,'dome',false],
  LA:['SoFi Stadium',33.9535,-118.3392,'dome',false],
  LAR:['SoFi Stadium',33.9535,-118.3392,'dome',false],
  MIA:['Hard Rock Stadium',25.9580,-80.2389,'outdoor',false],
  MIN:['U.S. Bank Stadium',44.9736,-93.2575,'dome',false],
  NE:['Gillette Stadium',42.0909,-71.2643,'outdoor',false],
  NO:['Caesars Superdome',29.9511,-90.0812,'dome',false],
  NYG:['MetLife Stadium',40.8135,-74.0745,'outdoor',false],
  NYJ:['MetLife Stadium',40.8135,-74.0745,'outdoor',false],
  PHI:['Lincoln Financial Field',39.9008,-75.1675,'outdoor',false],
  PIT:['Acrisure Stadium',40.4468,-80.0158,'outdoor',false],
  SEA:['Lumen Field',47.5952,-122.3316,'outdoor',false],
  SF:["Levi's Stadium",37.4030,-121.9698,'outdoor',false],
  TB:['Raymond James Stadium',27.9759,-82.5033,'outdoor',false],
  TEN:['Nissan Stadium',36.1665,-86.7713,'outdoor',false],
  WAS:['Northwest Stadium',38.9077,-76.8645,'outdoor',false],
};

const norm = s => (s || '').toLowerCase().replace(/[^a-z0-9 ]/g, ' ').replace(/\s+/g, ' ').trim();
const resolveAbbr = (name) => {
  const n = norm(name);
  if (!n) return null;
  // 1) nickname (unique) — disambiguates NYG/NYJ and LA/LAC/LAR
  for (const abbr of Object.keys(TEAMS)) { if (n.includes(norm(TEAMS[abbr][2]))) return abbr; }
  // 2) full name
  for (const abbr of Object.keys(TEAMS)) { if (n === norm(TEAMS[abbr][0]) || n.includes(norm(TEAMS[abbr][0]))) return abbr; }
  // 3) raw abbreviation string
  const up = (name || '').toUpperCase().trim();
  if (TEAMS[up]) return up;
  return null;
};

const awayAbbr = resolveAbbr(awayReq);
const homeAbbr = resolveAbbr(homeReq);

const games = items.map(i => i.json).filter(g => g && g.away_team && g.home_team);
const sameTeam = (a, b) => a === b || (TEAMS[a] && TEAMS[b] && TEAMS[a][0] === TEAMS[b][0]);

let matched = null;
for (const g of games) {
  if (awayAbbr && homeAbbr && sameTeam(g.away_team, awayAbbr) && sameTeam(g.home_team, homeAbbr)) { matched = g; break; }
  if (awayAbbr && homeAbbr && sameTeam(g.away_team, homeAbbr) && sameTeam(g.home_team, awayAbbr)) { matched = g; break; }
}

const st = abbr => STADIUMS[abbr] || [null, null, null, 'outdoor', false];
let fixture = null;
if (matched) {
  const a = matched.away_team, h = matched.home_team, hs = st(h);
  fixture = {
    game_id:        matched.game_id,
    gameday:        matched.gameday,
    gametime:       matched.gametime,
    weekday:        matched.weekday,
    season:         matched.season,
    week:           matched.week,
    game_type:      matched.game_type,
    div_game:       matched.div_game === '1' || matched.div_game === 1,
    away_abbr:      a,
    home_abbr:      h,
    away_team_name: (TEAMS[a] ? TEAMS[a][0] : a),
    home_team_name: (TEAMS[h] ? TEAMS[h][0] : h),
    away_rest:      matched.away_rest,
    home_rest:      matched.home_rest,
    away_qb_name:   matched.away_qb_name,
    home_qb_name:   matched.home_qb_name,
    spread_line:    matched.spread_line,
    total_line:     matched.total_line,
    stadium:        hs[0] || matched.stadium || null,
    home_lat:       hs[1],
    home_lon:       hs[2],
    roof:           hs[3],
    altitude:       hs[4],
    schedule_roof:  matched.roof || null,
  };
}

let wk = {};
try { wk = $('NFL Resolve Week').first().json || {}; } catch (e) {}
const scheduleFailed = !!(wk._schedule_error || wk._no_schedule || wk._no_games);

return [{
  json: {
    fixture,
    fixtureFound: !!fixture,
    schedule_error: scheduleFailed && !fixture,
    fixtureNote: fixture
      ? ('Matched nflverse game ' + fixture.game_id + ' (' + fixture.away_abbr + ' @ ' + fixture.home_abbr + ')')
      : scheduleFailed
        ? ('SCHEDULE DATA UNAVAILABLE — the nflverse games.csv fetch did not return a complete slate (' + (wk._schedule_msg || 'incomplete data') + '). This is a temporary data-fetch problem, NOT a missing game. Do not analyze; tell the user the schedule feed is loading and to try again in a moment.')
        : ('No ' + (wk._season || '') + ' week ' + (wk._week || '') + ' game found for ' + awayReq + ' vs ' + homeReq),
  }
}];

// NFL analog of CFB Assemble Context. Collapses all context to a single item the
// Bobby Vegas prompt reads. Records are derived from the same games.csv already
// fetched (completed games this season); injuries and weather come from their own
// fetches. No CFB talent-gap / roster-confidence caveats — the NFL mandates injury
// reporting, so listed absences are treated as real signal.
const NL = String.fromCharCode(10);
const fixture     = $('NFL Match Fixture').first().json.fixture;
const fixtureNote = $('NFL Match Fixture').first().json.fixtureNote;

const csvParse = raw => {
  const lines = (raw || '').trim().split(/\r?\n/).filter(Boolean);
  if (lines.length < 2) return [];
  const header = lines[0].split(',').map(h => h.trim());
  const out = [];
  for (let i = 1; i < lines.length; i++) {
    const cols = lines[i].split(',');
    if (cols.length < header.length) continue;
    const o = {}; header.forEach((h, j) => { o[h] = (cols[j] == null ? '' : String(cols[j]).trim()); });
    out.push(o);
  }
  return out;
};

// ---- season records from games.csv (completed games only) ----
let sched = [];
try { sched = csvParse($('NFL Get Schedule').first().json.data); } catch (e) {}

const recFor = (abbr, season) => {
  let w = 0, l = 0, t = 0, hw = 0, hl = 0, aw = 0, al = 0;
  for (const g of sched) {
    if (String(g.season) !== String(season)) continue;
    if (g.home_score === '' || g.away_score === '') continue;
    const hs = parseInt(g.home_score, 10), as = parseInt(g.away_score, 10);
    if (isNaN(hs) || isNaN(as)) continue;
    if (g.home_team === abbr) { if (hs > as) { w++; hw++; } else if (hs < as) { l++; hl++; } else { t++; } }
    else if (g.away_team === abbr) { if (as > hs) { w++; aw++; } else if (as < hs) { l++; al++; } else { t++; } }
  }
  return { w, l, t, hw, hl, aw, al };
};
const recLine = (label, abbr, season) => {
  const r = recFor(abbr, season);
  const rec = r.w + '-' + r.l + (r.t ? '-' + r.t : '');
  return label + ': ' + rec + ' overall | ' + r.hw + '-' + r.hl + ' home | ' + r.aw + '-' + r.al + ' away';
};

// ---- injuries from injuries_<season>.csv (final weekly designations) ----
let injRows = [];
try { injRows = csvParse($('NFL Get Injuries').first().json.data); } catch (e) {}

const KEY_POS = ['QB', 'LT', 'LG', 'C', 'RG', 'RT', 'T', 'G', 'OL', 'OT', 'OG'];
const injFor = (abbr, week) => {
  const rows = injRows.filter(r => r.team === abbr && (week == null || String(r.week) === String(week)));
  if (!rows.length) return null;
  const sev = s => ({ 'Out': 3, 'Doubtful': 2, 'Questionable': 1 }[s] || 0);
  const isKey = p => KEY_POS.includes((p || '').toUpperCase());
  rows.sort((a, b) => (isKey(b.position) - isKey(a.position)) || (sev(b.report_status) - sev(a.report_status)));
  return rows.map(r => {
    const parts = [(r.full_name || r.position || 'Player'), '(' + (r.position || '?') + ')'];
    if (r.report_status) parts.push(r.report_status);
    const inj = r.report_primary_injury || r.practice_primary_injury;
    if (inj) parts.push('- ' + inj);
    if (r.practice_status) parts.push('[practice: ' + r.practice_status + ']');
    return parts.join(' ');
  });
};

// ---- weather from Open-Meteo (wind-forward; skip indoor) ----
const weatherStr = (() => {
  if (!fixture) return 'Weather unavailable';
  if (fixture.roof === 'dome') return 'Indoor stadium (' + (fixture.stadium || 'dome') + ') — weather not a factor';
  let wx = null;
  try { wx = $('NFL Get Weather').first().json; } catch (e) {}
  const h = wx && wx.hourly ? wx.hourly : null;
  if (!h || !Array.isArray(h.time)) {
    return (fixture.roof === 'retractable' ? 'Retractable roof (' + (fixture.stadium || '') + ') — assume closed unless reported open; ' : '') + 'No live weather forecast available';
  }
  const kick = fixture.gameday ? new Date(fixture.gameday + 'T' + (fixture.gametime || '13:00') + ':00Z').getTime() : Date.now();
  let bi = 0, bd = Infinity;
  for (let i = 0; i < h.time.length; i++) {
    const d = Math.abs(new Date(h.time[i] + ':00Z').getTime() - kick);
    if (d < bd) { bd = d; bi = i; }
  }
  const at = (arr) => (arr && arr[bi] != null) ? Math.round(arr[bi]) : null;
  const wind = at(h.wind_speed_10m), gust = at(h.wind_gusts_10m), temp = at(h.temperature_2m), pop = at(h.precipitation_probability);
  const windNote = wind == null ? '' : (wind >= 20 ? ' — HIGH WIND, major passing/kicking suppressor' : wind >= 15 ? ' — notable wind, tilts toward the under and the run' : ' — light wind');
  const parts = ['Wind ' + (wind == null ? '?' : wind) + ' mph' + (gust ? ' (gusts ' + gust + ')' : '') + windNote];
  if (temp != null) parts.push('Temp ' + temp + 'F');
  if (pop != null) parts.push('Precip ' + pop + '%');
  const head = (fixture.roof === 'retractable') ? 'Retractable roof — forecast if open: ' : '';
  const alt = fixture.altitude ? ' | ALTITUDE: Denver mile-high air extends kicking range and ball flight — separate from weather' : '';
  return head + parts.join(' | ') + alt;
})();

// ---- rest differential ----
const restStr = (() => {
  if (!fixture) return 'Rest data unavailable';
  const ar = parseInt(fixture.away_rest, 10), hr = parseInt(fixture.home_rest, 10);
  if (isNaN(ar) || isNaN(hr)) return 'Rest data unavailable';
  const diff = hr - ar;
  let note = 'even rest';
  if (Math.abs(diff) >= 3) note = (diff > 0 ? fixture.home_team_name : fixture.away_team_name) + ' has a significant rest edge (' + Math.abs(diff) + ' extra days)';
  else if (Math.abs(diff) >= 1) note = (diff > 0 ? fixture.home_team_name : fixture.away_team_name) + ' is slightly better rested';
  const shortFlag = (ar <= 4 || hr <= 4) ? ' | SHORT REST in play (Thursday / short turnaround)' : '';
  return fixture.away_team_name + ' ' + ar + ' days / ' + fixture.home_team_name + ' ' + hr + ' days — ' + note + shortFlag;
})();

// ---- build strings ----
let formStr = 'Team form not available';
let gameStr = 'Matchup details not available';
let homeFieldStr = 'Venue unconfirmed';
let injuryStr = 'No injury report data available';

if (fixture) {
  formStr = recLine(fixture.away_team_name, fixture.away_abbr, fixture.season) + ' || ' +
            recLine(fixture.home_team_name, fixture.home_abbr, fixture.season);

  gameStr = fixture.away_team_name + ' at ' + fixture.home_team_name + ' | ' +
            'Kickoff: ' + (fixture.gameday || 'TBD') + ' ' + (fixture.gametime || '') + ' | ' +
            (fixture.game_type && fixture.game_type !== 'REG' ? fixture.game_type + ' | ' : '') +
            'Divisional game: ' + (fixture.div_game ? 'Yes' : 'No') + ' | ' +
            'QBs: ' + (fixture.away_qb_name || 'TBD') + ' vs ' + (fixture.home_qb_name || 'TBD');

  homeFieldStr = (fixture.stadium || 'Home venue') + ' — home crowd and travel favor ' + fixture.home_team_name +
                 (fixture.roof === 'dome' ? ' (indoor)' : fixture.roof === 'retractable' ? ' (retractable roof)' : ' (outdoor)');

  const ai = injFor(fixture.away_abbr, fixture.week);
  const hi = injFor(fixture.home_abbr, fixture.week);
  const block = (name, list) => name + ':' + NL + (list && list.length ? '  - ' + list.slice(0, 12).join(NL + '  - ') : '  - No injuries listed');
  if (ai || hi) {
    injuryStr = block(fixture.away_team_name, ai) + NL + block(fixture.home_team_name, hi);
  } else {
    injuryStr = 'No injury report rows found for week ' + fixture.week + ' (report may not be posted yet)';
  }
}

return [{
  json: {
    fixture,
    fixtureNote,
    form_str:       formStr,
    game_str:       gameStr,
    home_field_str: homeFieldStr,
    rest_str:       restStr,
    weather_str:    weatherStr,
    injury_str:     injuryStr,
  }
}];

// Match the nflverse-confirmed game to its Odds API entry.
// Odds API uses full "City Nickname" names ("Kansas City Chiefs"); our fixture
// already carries the canonical full names. Match on NICKNAME (the last word),
// which is unique across all 32 teams — this is what stops the two New York and
// two Los Angeles clubs from cross-matching. City alone never scores a match.
// Get NFL Odds may emit the board as many items OR as one item wrapping the array.
let oddsGames = [];
for (const r of $input.all().map(i => i.json)) {
  if (Array.isArray(r)) oddsGames = oddsGames.concat(r);
  else if (r && r.home_team && r.away_team) oddsGames.push(r);
  else if (r && Array.isArray(r.data)) oddsGames = oddsGames.concat(r.data);
  else if (r && Array.isArray(r.body)) oddsGames = oddsGames.concat(r.body);
}
oddsGames = oddsGames.filter(g => g && g.home_team && g.away_team);

let fixture = null;
try { fixture = $('NFL Match Fixture').first().json.fixture; } catch (e) {}

const empty = { odds_matched: false, odds_str: 'No sportsbook odds matched for this game', odds_raw: '' };
if (!fixture) { return [{ json: empty }]; }

const fixAway = fixture.away_team_name || '';
const fixHome = fixture.home_team_name || '';

const norm = s => (s || '')
  .normalize('NFD').replace(/[̀-ͯ]/g, '')
  .toLowerCase().replace(/[^a-z0-9 ]/g, ' ').replace(/\s+/g, ' ').trim();
const nick = s => { const w = norm(s).split(' ').filter(Boolean); return w.length ? w[w.length - 1] : ''; };

// 3 = exact full-name match, 2 = same nickname, 0 = no match (city alone never matches).
const score = (a, b) => {
  const na = norm(a), nb = norm(b);
  if (!na || !nb) return 0;
  if (na === nb) return 3;
  const ka = nick(a), kb = nick(b);
  if (ka && ka === kb) return 2;
  return 0;
};

let best = null, bestScore = 0;
for (const g of oddsGames) {
  const straight = (score(fixAway, g.away_team) && score(fixHome, g.home_team))
    ? score(fixAway, g.away_team) + score(fixHome, g.home_team) : 0;
  const swapped = (score(fixAway, g.home_team) && score(fixHome, g.away_team))
    ? score(fixAway, g.home_team) + score(fixHome, g.away_team) : 0;
  const gs = Math.max(straight, swapped);
  if (gs > bestScore) { bestScore = gs; best = g; }
}

if (!best) { return [{ json: empty }]; }

const px = p => (p > 0 ? '+' + p : '' + p);
const bm = (best.bookmakers || [])[0];
const mkts = bm ? (bm.markets || []) : [];
const h2h = mkts.find(m => m.key === 'h2h');
const spr = mkts.find(m => m.key === 'spreads');

const parts = [];
let book_away_ml = null, book_home_ml = null;
let book_away_spread = null, book_home_spread = null, book_away_spread_price = null, book_home_spread_price = null;
if (h2h) {
  const a  = (h2h.outcomes || []).find(o => o.name === best.away_team);
  const hh = (h2h.outcomes || []).find(o => o.name === best.home_team);
  if (a && hh) {
    book_away_ml = a.price; book_home_ml = hh.price;
    parts.push('Moneyline: ' + best.away_team + ' ' + px(a.price) + ' / ' + best.home_team + ' ' + px(hh.price));
  }
}
if (spr) {
  const a  = (spr.outcomes || []).find(o => o.name === best.away_team);
  const hh = (spr.outcomes || []).find(o => o.name === best.home_team);
  if (a && hh && a.point !== undefined && hh.point !== undefined) {
    book_away_spread = a.point; book_home_spread = hh.point;
    book_away_spread_price = a.price ?? null; book_home_spread_price = hh.price ?? null;
    parts.push('Spread: ' + best.away_team + ' ' + px(a.point) + ' / ' + best.home_team + ' ' + px(hh.point));
  }
}

return [{
  json: {
    odds_matched: parts.length > 0,
    odds_str:     parts.length ? parts.join(' | ') : 'Matched game but no h2h/spread markets posted yet',
    odds_raw:     JSON.stringify(best).slice(0, 1500),
    odds_book:    bm ? (bm.title || bm.key || 'book') : null,
    book_away_ml, book_home_ml,
    book_away_spread, book_home_spread, book_away_spread_price, book_home_spread_price,
  }
}];

// ===== Match Kalshi Teams (single-sided "X wins" market model, NFL) =====
// The NFL odds_cache stores ONE market per team: title "Denver wins",
// yes_sub_title "Denver", yes_bid_dollars = P(that team wins). A game is the
// PAIR of the home team's and away team's "wins" markets, so each leg is matched
// separately (not the two-way "Team A vs Team B" title model the other sports
// use). Team labels are city names, disambiguated for the two Los Angeles / two
// New York clubs by a trailing nickname initial ("Los Angeles C" = Chargers,
// "New York G" = Giants). If only one leg is listed, the other side is the
// complement of that "X wins" contract (NFL ties are negligible).

const items    = $input.all();
const awayTeam = $('Parse Teams').first().json.away_team || '';
const homeTeam = $('Parse Teams').first().json.home_team || '';

const norm = s => (s || '')
  .normalize('NFD').replace(/[̀-ͯ]/g, '')
  .toLowerCase().replace(/[^a-z0-9 ]/g, ' ').replace(/\s+/g, ' ').trim();

// Does a Kalshi label ("Denver", "Los Angeles C") identify a full team name
// ("Denver Broncos", "Los Angeles Rams")? Every city token must appear in the
// full name; a trailing single letter must equal the first letter of the
// nickname (the requested tokens beyond the shared city) — this disambiguates
// the two Los Angeles / two New York clubs.
const labelMatches = (label, fullName) => {
  const L = norm(label).split(' ').filter(Boolean);
  const R = norm(fullName).split(' ').filter(Boolean);
  if (!L.length || !R.length) return false;
  const last = L[L.length - 1];
  const hasInitial = last.length === 1;
  const city = hasInitial ? L.slice(0, -1) : L;
  if (!city.length || !city.every(t => R.includes(t))) return false;
  if (hasInitial) {
    const nick = R.filter(t => !city.includes(t));
    if (!nick.length || nick[0][0] !== last) return false;
  }
  return true;
};

const labelOf = m => (m.yes_sub_title && String(m.yes_sub_title).trim())
  ? String(m.yes_sub_title).trim()
  : String(m.title || '').replace(/\s+wins?\??$/i, '').trim();

const yesPct = m => {
  const yd = m.yes_bid_dollars != null ? m.yes_bid_dollars
           : (m.last_price_dollars != null ? m.last_price_dollars : null);
  return yd !== null ? parseFloat(yd) * 100 : null;
};
const volOf = m => m ? (parseFloat(m.volume_fp || 0) || 0) : 0;

let kalshiEdge = null;

try {
  const cacheRow = items[0] && items[0].json;
  const markets  = cacheRow && cacheRow.data && cacheRow.data.markets;

  if (Array.isArray(markets) && markets.length > 0 && homeTeam && homeTeam !== 'General') {
    const homeLeg = markets.find(m => labelMatches(labelOf(m), homeTeam));
    const awayLeg = markets.find(m => labelMatches(labelOf(m), awayTeam));

    if (homeLeg || awayLeg) {
      const homeYes = homeLeg ? yesPct(homeLeg) : null;
      const awayYes = awayLeg ? yesPct(awayLeg) : null;
      const homePct = homeYes !== null ? homeYes : (awayYes !== null ? 100 - awayYes : null);
      const awayPct = awayYes !== null ? awayYes : (homeYes !== null ? 100 - homeYes : null);

      if (homePct !== null || awayPct !== null) {
        kalshiEdge = {
          market:           (homeLeg || awayLeg).title || (awayTeam + ' at ' + homeTeam),
          home_team:        homeTeam,
          away_team:        awayTeam,
          home_implied_pct: homePct !== null ? homePct.toFixed(1) : 'n/a',
          away_implied_pct: awayPct !== null ? awayPct.toFixed(1) : 'n/a',
          volume:           (volOf(homeLeg) + volOf(awayLeg)).toFixed(0),
          legs:             (homeLeg && awayLeg) ? 'both' : (homeLeg ? 'home-only (away = complement)' : 'away-only (home = complement)'),
        };
      }
    }
  }
} catch (e) {}

return [{
  json: {
    ...(items[0] && items[0].json ? items[0].json : {}),
    kalshi_edge:      kalshiEdge,
    kalshi_available: kalshiEdge !== null,
  }
}];

// NFL Model Line — Bobby's independent number from the power ratings, compared
// to the book. expected_margin(home) = home_rating - away_rating + HFA + rest;
// edge = model margin - book margin. Feeds the four-tier read and the pick log.
const flatten = items => {
  let out = [];
  for (const r of items.map(i => i.json)) {
    if (Array.isArray(r)) out = out.concat(r);
    else if (r && r.team && r.rating !== undefined && r.rating !== null) out.push(r);
    else if (r && Array.isArray(r.data)) out = out.concat(r.data);
  }
  return out;
};

let ratingRows = [];
try { ratingRows = flatten($('Get Team Ratings').all()); } catch (e) {}
let fixture = null;
try { fixture = $('NFL Match Fixture').first().json.fixture; } catch (e) {}
let odds = {};
try { odds = $('Match NFL Odds').first().json || {}; } catch (e) {}

const empty = {
  model_available: false,
  model_line_str: 'Model line unavailable — no power rating for one or both teams (run the ratings workflow)',
  model_spread: null, book_spread: null, edge_pts: null, edge_side: null, crosses_key: [],
  rating_week: null, early_uncertainty: false, kalshi_corroborates: false,
};
if (!fixture) { return [{ json: empty }]; }

// latest rating per team
const latest = {};
for (const r of ratingRows) {
  const wk = parseInt(r.week, 10) || 0;
  if (!latest[r.team] || wk > latest[r.team].week) latest[r.team] = { week: wk, rating: parseFloat(r.rating) };
}
const hAbbr = fixture.home_abbr, aAbbr = fixture.away_abbr;
const hr = latest[hAbbr] ? latest[hAbbr].rating : undefined;
const ar = latest[aAbbr] ? latest[aAbbr].rating : undefined;
if (hr === undefined || ar === undefined || isNaN(hr) || isNaN(ar)) { return [{ json: empty }]; }
const rating_week = Math.max(latest[hAbbr].week || 0, latest[aAbbr].week || 0);

// rest adjustment: +1 pt per 3-day home rest edge, capped ±3
const aRest = parseInt(fixture.away_rest, 10), hRest = parseInt(fixture.home_rest, 10);
let rest_adj = 0;
if (!isNaN(aRest) && !isNaN(hRest)) rest_adj = Math.max(-3, Math.min(3, (hRest - aRest) / 3));

const HFA = 1.8;
const model_home_margin = hr - ar + HFA + rest_adj;        // + = home favored
const model_spread_home = -model_home_margin;              // home spread (neg = home favored)
const book_spread_home = (odds.book_home_spread != null && odds.book_home_spread !== '') ? parseFloat(odds.book_home_spread) : null;
const book_home_margin = book_spread_home != null && !isNaN(book_spread_home) ? -book_spread_home : null;

const hName = fixture.home_team_name, aName = fixture.away_team_name;
const fmt = s => (s > 0 ? '+' : '') + s.toFixed(1);

const modelFavName = model_home_margin >= 0 ? hName : aName;
const modelFavSpread = -Math.abs(model_home_margin);

let bookStr = 'unavailable';
if (book_home_margin != null) {
  const bookFavName = book_home_margin >= 0 ? hName : aName;
  bookStr = bookFavName + ' ' + fmt(-Math.abs(book_home_margin));
}

let edge_pts = null, edge_side = null, edge_side_abbr = null, crosses = [];
if (book_home_margin != null) {
  const diff = model_home_margin - book_home_margin;       // + = model likes home more than book
  edge_pts = Math.round(Math.abs(diff) * 10) / 10;
  edge_side = diff > 0 ? hName : aName;
  edge_side_abbr = diff > 0 ? hAbbr : aAbbr;
  for (const k of [3, 7]) {
    const lo = Math.min(Math.abs(model_home_margin), Math.abs(book_home_margin));
    const hi = Math.max(Math.abs(model_home_margin), Math.abs(book_home_margin));
    if (lo < k && hi >= k) crosses.push(k);
  }
}

// Does Kalshi corroborate the model edge? (gate passed + same side). This exempts
// a large early-season edge from the uncertainty cap.
let kalshi_corroborates = false;
try {
  const mk = $('Match Kalshi Teams').first().json;
  if (mk && mk.kalshi_available && mk.kalshi_edge && edge_side_abbr) {
    const vol = parseFloat(mk.kalshi_edge.volume);
    const hp = parseFloat(mk.kalshi_edge.home_implied_pct), ap = parseFloat(mk.kalshi_edge.away_implied_pct);
    if (!isNaN(vol) && vol >= 5000 && !isNaN(hp) && !isNaN(ap)) {
      const kSide = hp >= ap ? hAbbr : aAbbr;
      kalshi_corroborates = kSide === edge_side_abbr;
    }
  }
} catch (e) {}

// Early-season model uncertainty: a >5 pt edge in weeks 1-6, pure model only.
// A small sample rarely produces a real 5+ point disagreement with the market;
// the tier is capped at Lean downstream unless Kalshi corroborates.
const early_uncertainty = rating_week <= 6 && edge_pts != null && edge_pts > 5 && !kalshi_corroborates;

const model_line_str = 'Bobby number ' + modelFavName + ' ' + fmt(modelFavSpread) +
  ' | Book ' + bookStr +
  (edge_pts != null ? (' | Edge ' + edge_pts.toFixed(1) + ' toward ' + edge_side) : ' | Edge n/a (no book spread)') +
  (crosses.length ? ' (crosses key ' + crosses.join(' & ') + ')' : '') +
  (early_uncertainty ? ' | EARLY-SEASON MODEL UNCERTAINTY: >5 pt edge in week ' + rating_week + ' off a small sample — cap the tier at LEAN' : '');

return [{
  json: {
    model_available: true,
    model_line_str,
    model_spread: Math.round(model_spread_home * 10) / 10,
    book_spread: book_spread_home,
    edge_pts,
    edge_side, edge_side_abbr,
    crosses_key: crosses,
    rating_week,
    early_uncertainty,
    kalshi_corroborates,
    home_rating: hr, away_rating: ar, rest_adj: Math.round(rest_adj * 10) / 10,
  },
}];

