// Parse Bobby's PICK_JSON footer (tier/pick_type/side/confidence) and merge the
// deterministic model, odds, and Kalshi fields into a single pick_log row.
const content = (() => { try { return $('Bobby Vegas Analysis').first().json.message.content || ''; } catch (e) { return ''; } })();

let footer = {};
const m = content.match(/PICK_JSON:\s*(\{[\s\S]*?\})\s*$/);
if (m) { try { footer = JSON.parse(m[1]); } catch (e) {} }

const pt = $('Parse Teams').first().json;
const wh = $('Webhook').first().json.body ?? $('Webhook').first().json;
let ml = {}; try { ml = $('NFL Model Line').first().json || {}; } catch (e) {}
let mo = {}; try { mo = $('Match NFL Odds').first().json || {}; } catch (e) {}
let fx = null; try { fx = $('NFL Match Fixture').first().json.fixture; } catch (e) {}
let ke = null; try { const mk = $('Match Kalshi Teams').first().json; if (mk.kalshi_available) ke = mk.kalshi_edge; } catch (e) {}

const side = footer.side || null;
const pick_type = footer.pick_type || null;

// Deterministic early-season cap: a flagged >5 pt week-1-6 model edge (no Kalshi
// corroboration) can never be logged as a Strong Play — downgrade it to Lean.
const early_uncertainty = !!(ml && ml.early_uncertainty);
let tier = footer.tier || null;
if (early_uncertainty && tier && tier.toLowerCase().replace(/\s+/g, ' ').trim() === 'strong play') tier = 'Lean';
const norm = s => (s || '').toLowerCase();
const sideIsHome = () => fx && fx.home_team_name && side && norm(side).includes(norm(fx.home_team_name));
const sideIsAway = () => fx && fx.away_team_name && side && norm(side).includes(norm(fx.away_team_name));

// line + price at pick from the matched book, per side and bet type
let line_at_pick = null, price_at_pick = null;
if (fx && side) {
  if (pick_type === 'spread') {
    line_at_pick  = sideIsHome() ? mo.book_home_spread : sideIsAway() ? mo.book_away_spread : null;
    price_at_pick = sideIsHome() ? mo.book_home_spread_price : sideIsAway() ? mo.book_away_spread_price : null;
  } else if (pick_type === 'moneyline') {
    price_at_pick = sideIsHome() ? mo.book_home_ml : sideIsAway() ? mo.book_away_ml : null;
  }
}

// devigged sportsbook implied for the picked side
let sportsbook_implied = null;
if (mo.book_home_ml != null && mo.book_away_ml != null) {
  const imp = o => o > 0 ? 100 / (o + 100) : Math.abs(o) / (Math.abs(o) + 100);
  const rh = imp(mo.book_home_ml), ra = imp(mo.book_away_ml), sum = rh + ra;
  if (sum > 0) {
    if (sideIsHome()) sportsbook_implied = Math.round(rh / sum * 1000) / 10;
    else if (sideIsAway()) sportsbook_implied = Math.round(ra / sum * 1000) / 10;
  }
}

let kalshi_implied = null, kalshi_volume = null, gate_passed = null;
if (ke) {
  kalshi_volume = parseFloat(ke.volume); if (isNaN(kalshi_volume)) kalshi_volume = null;
  gate_passed = kalshi_volume != null ? kalshi_volume >= 5000 : null;
  const hp = parseFloat(ke.home_implied_pct), ap = parseFloat(ke.away_implied_pct);
  if (sideIsHome()) kalshi_implied = isNaN(hp) ? null : hp;
  else if (sideIsAway()) kalshi_implied = isNaN(ap) ? null : ap;
}

const source    = (wh && wh.test) ? 'test' : 'app';
const game_date = (wh && wh.targetDate) ? wh.targetDate : (fx && fx.gameday) ? fx.gameday : null;
const kickoff   = (fx && fx.gameday && fx.gametime) ? (fx.gameday + 'T' + fx.gametime + ':00Z') : null;
const num = v => (v != null && v !== '' && !isNaN(parseFloat(v))) ? parseFloat(v) : null;

const row = {
  sport: 'NFL',
  away: pt.away_team, home: pt.home_team,
  game_date, kickoff,
  tier,
  early_uncertainty,
  pick_type, side,
  line_at_pick: num(line_at_pick),
  price_at_pick: price_at_pick != null ? parseInt(price_at_pick, 10) : null,
  model_spread: ml.model_spread != null ? ml.model_spread : null,
  book_spread: ml.book_spread != null ? ml.book_spread : null,
  edge_pts: ml.edge_pts != null ? ml.edge_pts : null,
  sportsbook_implied, kalshi_implied, kalshi_volume, gate_passed,
  confidence: footer.confidence || null,
  model: 'gpt-5',
  prompt_version: 'nfl-v2-model-1',
  source,
  full_response: content,
};

return [{ json: { row } }];
